const teamInfo = $('Loop: Split Teams').first().json;
const fixtureResp = $input.first().json;
const fixture = (fixtureResp.data || [])[0];
if (!fixture) return [{ json: { ...teamInfo, skip: true } }];
const f = fixture.fixture || {};
const homeId = f.home_competitors?.[0]?.id;
const isHome = homeId === teamInfo.opticoddsId;
const homeScore = fixture.scores?.home?.total ?? 0;
const awayScore = fixture.scores?.away?.total ?? 0;
const goalsFor     = isHome ? homeScore : awayScore;
const goalsAgainst = isHome ? awayScore : homeScore;
const opponentName = isHome
  ? (f.away_team_display || f.away_competitors?.[0]?.name || 'Unknown')
  : (f.home_team_display || f.home_competitors?.[0]?.name || 'Unknown');
const opponentId = isHome ? f.away_competitors?.[0]?.id : f.home_competitors?.[0]?.id;
const events   = fixture.events || [];
const myStats  = ((isHome ? fixture.stats?.home : fixture.stats?.away) || []).find(s => s.period === 'all')?.stats || {};
const oppStats = ((isHome ? fixture.stats?.away : fixture.stats?.home) || []).find(s => s.period === 'all')?.stats || {};
const competition = fixture.league?.name || fixture.league?.id || '';
return [{ json: { ...teamInfo, teamId: teamInfo.opticoddsId, opponentName, opponentId, isHome, goalsFor, goalsAgainst, matchId: f.id, matchDate: f.start_date, competition, events, myStats, oppStats } }];

const teamData = $('Extract Match Data').first().json;
const nextMatchResp = $('Fetch Next Match').first().json;
const injuriesResp = $input.first().json;

const nextFixtures = nextMatchResp.data || [];
const nextFixture = nextFixtures[0] || null;
let nextOpponent = 'TBD', nextMatchDate = null, nextCompetition = 'TBD';
if (nextFixture) {
  const nf = nextFixture.fixture || {};
  const homeId = nf.home_competitors?.[0]?.id;
  const isHome = homeId === teamData.teamId;
  nextOpponent = isHome
    ? (nf.away_team_display || nf.away_competitors?.[0]?.name || 'TBD')
    : (nf.home_team_display || nf.home_competitors?.[0]?.name || 'TBD');
  nextMatchDate = nf.start_date;
  nextCompetition = nextFixture.league?.name || 'TBD';
}

const injuries = (injuriesResp.data || [])
  .filter(inj => inj.player?.name)
  .slice(0, 5)
  .map(inj => ({ name: inj.player.name, position: inj.player.position || '', status: inj.status, type: inj.type }));

const goalEvents = (teamData.events || []).filter(e => {
  const t = (e.type || e.event_type || '').toLowerCase();
  return t.includes('goal') && (e.team_id === teamData.teamId || e.competitor_id === teamData.teamId);
});
const goalScorers = goalEvents.map(e => e.player_name || e.player?.name).filter(Boolean);

const { goalsFor, goalsAgainst } = teamData;
const result = goalsFor > goalsAgainst ? 'WIN' : goalsFor < goalsAgainst ? 'LOSS' : 'DRAW';
return [{ json: { ...teamData, result, nextOpponent, nextMatchDate, nextCompetition, injuries, goalScorers } }];

const d = $input.first().json;
let nextFixtureText = 'No upcoming match currently scheduled.';
if (d.nextMatchDate) {
  const dt = new Date(d.nextMatchDate);
  const formatted = dt.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
  nextFixtureText = 'Next: ' + d.nextOpponent + ' (' + d.nextCompetition + ') - ' + formatted;
}
const lines = [
  'Update the website for ' + d.teamName + '.',
  '',
  'MATCH:',
  '- ' + d.competition + ' | ' + (d.isHome ? 'Home' : 'Away') + ' vs ' + d.opponentName,
  '- Result: ' + d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst
];
if (d.goalScorers && d.goalScorers.length > 0) {
  lines.push('- Goals: ' + d.goalScorers.join(', '));
}
if (d.myStats && Object.keys(d.myStats).length > 0) {
  const s = d.myStats;
  const parts = [];
  if (s.shots !== undefined) parts.push('Shots ' + s.shots + (s.shots_on_target !== undefined ? ' (' + s.shots_on_target + ' on target)' : ''));
  if (s.possession !== undefined) parts.push('Possession ' + s.possession + '%');
  if (s.corners !== undefined) parts.push('Corners ' + s.corners);
  if (parts.length > 0) lines.push('- Stats: ' + parts.join(' | '));
}
lines.push('', 'NEXT MATCH: ' + nextFixtureText);
if (d.injuries && d.injuries.length > 0) {
  lines.push('', 'INJURY LIST:');
  d.injuries.forEach(inj => {
    lines.push('- ' + inj.name + (inj.position ? ' (' + inj.position + ')' : '') + ': ' + inj.status + ' - ' + inj.type);
  });
}
lines.push('', "Write a punchy, supporter-facing 2-3 sentence update for the team's website. Requirements:", '1. Open with the result and score - mention the scorer(s) if available', '2. Include a performance detail from the stats if provided', '3. Close with the next fixture', '4. If there are injuries, weave in one concern naturally', '', 'Return ONLY plain text - no HTML, no markdown, no quotes.');
const prompt = lines.join('\n');
const claudeBody = { model: 'claude-sonnet-4-6', max_tokens: 300, messages: [{ role: 'user', content: prompt }] };
return [{ json: { ...d, prompt, claudeBody } }];

const claudeResp = $input.first().json;
const promptData = $('Build Claude Prompt').first().json;
const generatedContent = claudeResp.content?.[0]?.text?.trim() || '';
if (!generatedContent) {
  throw new Error('Claude returned empty content for ' + promptData.teamName);
}
const resultEmoji = promptData.result === 'WIN' ? ':white_check_mark:' : promptData.result === 'LOSS' ? ':x:' : ':heavy_minus_sign:';
const scoreText = promptData.goalsFor + '-' + promptData.goalsAgainst;
const scorerLine = promptData.goalScorers?.length > 0 ? 'Goals: ' + promptData.goalScorers.join(', ') : null;
const contextParts = ['Premier League'];
if (promptData.nextOpponent !== 'TBD') contextParts.push('Next: ' + promptData.nextOpponent + ' (' + promptData.nextCompetition + ')');
if (promptData.injuries?.length > 0) contextParts.push('Injuries: ' + promptData.injuries.length);
const slackBody = {
  text: promptData.teamName + ' | ' + promptData.result + ' ' + scoreText + ' vs ' + promptData.opponentName,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: promptData.teamName + '  |  ' + promptData.result + ' ' + scoreText, emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: resultEmoji + '  *vs ' + promptData.opponentName + '*  (Premier League)' + (scorerLine ? '\n' + scorerLine : '') + '\n\n' + generatedContent } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: contextParts.join('  |  ') }] }
  ]
};
return [{ json: { ...promptData, generatedContent, slackBody } }];

const d = $('Parse Claude Response').first().json;
const ts = new Date().toISOString();
console.log('[' + ts + '] OK | ' + d.teamName + ' | Slack sent | ' + d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst + ' vs ' + d.opponentName);
return [{ json: { success: true, timestamp: ts, team: d.teamName, result: d.result + ' ' + d.goalsFor + '-' + d.goalsAgainst, opponent: d.opponentName, competition: d.competition, goalScorers: d.goalScorers, injuries: (d.injuries || []).length } }];
